class Solution { public int[] threeEqualParts(int[] arr){int ones=0;for(int bit:arr)ones+=bit;if(ones==0)return new int[]{0,2};if(ones%3!=0)return new int[]{-1,-1};int part=ones/3,first=-1,second=-1,third=-1,seen=0;for(int i=0;i<arr.length;i++)if(arr[i]==1){seen++;if(seen==1)first=i;else if(seen==part+1)second=i;else if(seen==2*part+1)third=i;}int length=arr.length-third;if(first+length>second||second+length>third)return new int[]{-1,-1};for(int i=0;i<length;i++)if(arr[first+i]!=arr[second+i]||arr[first+i]!=arr[third+i])return new int[]{-1,-1};return new int[]{first+length-1,second+length};} }
